import { io } from "socket.io-client";
import { store } from "@/store/index.js";
// 创建socket实例（注意：生产环境应使用HTTPS）
export const socket = io("http://localhost:2525", {
  autoConnect: true,
  transports: ["websocket"],
});
// 连接Socket并设置事件监听
export function connectSocket() {// 必须手动连接
  socket.on("connect", () => {
    console.log("Socket connected");
  });
  socket.on("disconnect", () => {
    socket.open()
    socket.emit('a',localStorage.getItem("UresName"))
    console.log(1111111111111111)
    socket.close()
  });
  socket.on("connect_error", (error) => {
    console.error("Connection error:", error);
  });
}
// 发送消息
export function sendMessage() {
  socket.emit("message", "zhuj");
}
// 获取在线人数（需要后端配合）
export async function  requestOnlineNumbers() {
    socket.on("Online_Numbers", async (res) => {
      store.state.Online_Numbers = await res["name"];
      for(let i=0;i<store.state.Online_Numbers.length;i++){
        store.state.disconnectNumber=store.state.Urselist.filter((item)=> {
          return item !== store.state.Online_Numbers[i]
        })
      }
      })

    }
export async function Request_UseName(){
   socket.emit("UseName",localStorage.getItem('UresName'))
}
export default {
  connectSocket,
  sendMessage,
  requestOnlineNumbers,
  socket,
  Request_UseName
};
